L47_1 = "\227\129\167\227\130\130\227\131\161\227\130\164\227\130\189\227\131\179\227\129\149\227\130\147\227\129\140\230\140\129\227\129\163\227\129\166\227\129\141\227\129\166\227\129\143\227\130\140\227\129\159\227\131\142\227\131\180\227\130\161\231\180\154\227\131\170\227\130\162\227\130\175\227\130\191\227\131\188\227\129\149\227\129\136\227\129\130\227\130\140\227\129\176\227\128\129\n\233\128\134\232\168\173\232\168\136\227\129\140\229\143\175\232\131\189\227\129\167\227\129\153\227\128\130"
