L7_1 = "\227\129\161\227\130\135\227\129\163\227\129\168\232\187\139\227\130\128\227\129\160\227\130\141\227\129\134\227\129\140\227\128\129\227\130\183\227\130\185\227\131\134\227\131\160\232\170\191\230\149\180\227\129\175\229\191\131\233\133\141\227\129\153\227\130\139\227\129\170\227\128\130"
