L7_1 = "It might not run smoothly, but don\226\128\153t worry about controlling the system."
L6_1.m_Talk_ENG = L7_1
L7_1 = "\233\155\150\231\132\182\230\156\137\228\186\155\233\155\156\233\159\179\239\188\140\228\189\134\231\179\187\231\181\177\230\152\175\230\178\146\229\149\143\233\161\140\231\154\132\239\188\140\229\132\152\231\174\161\230\148\190\229\191\131\239\188\129"
