L6_1.m_Talk_VTN = L7_1
L7_1 = "\232\153\189\231\132\182\229\143\175\232\131\189\228\188\154\230\156\137\228\186\155\229\176\143\233\151\174\233\162\152\239\188\140\228\189\134\228\184\141\231\148\168\230\139\133\229\191\131\231\179\187\231\187\159\232\176\131\232\175\149\227\128\130"
